 $('#mission-panels').addEventListener('click',e=>{const download=e.target.closest('[data-download-mission]'),reset=e.target.closest('[data-reset-mission]');if(!download&&!reset)return;const button=download||reset,panel=button.closest('.mission-panel'),status=$('[data-mission-check-status]',panel);if(reset){if(blocked){status.textContent='Đọc lại dữ liệu đã lưu trước khi xóa phiếu.';return;}if(!confirm('Xóa ghi chép và dấu chọn của phiếu này trên trình duyệt? Hãy tải TXT nếu muốn giữ lại.'))return;try{clearTimeout(timers.get(panel.id));const entries={...state.entries};delete entries[panel.id];const next=X.practiceState({version:1,entries});raw=C.guardedSet(localStorage,'th-practice',next,raw);state=next;$$('[data-mission-check]',panel).forEach(input=>input.checked=false);$('[data-mission-note]',panel).value='';dirty.delete(panel.id);status.textContent='Đã xóa phiếu này trên trình duyệt.';summary();}catch(err){warning(err.message);status.textContent='Chưa xóa được phiếu.';}return;}try{const text=X.worksheet(D,download.dataset.downloadMission,{checks:$$('[data-mission-check]:checked',panel).map(input=>Number(input.dataset.missionCheck)),note:$('[data-mission-note]',panel).value}),blob=new Blob(['\uFEFF'+text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='Tech_Horizon_Thuc_Hanh_'+download.dataset.downloadMission+'.txt';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);status.textContent='Đã tạo phiếu TXT để tải xuống. Giữ tệp riêng nếu có ghi chép cá nhân.';}catch(err){status.textContent='Chưa tạo được phiếu: '+err.message;}});
 function updateReadState(){let progress={};try{progress=C.readerBackup({type:'tech-horizon-reader',version:1,saved:[],progress:C.storage.get('th-progress',{})},D.articles.map(a=>a.id)).progress;}catch{}$$('[data-mission-read-state]').forEach(label=>{const p=progress[label.dataset.missionReadState];label.textContent=p?.percent>=95?'· Đã đọc trên thiết bị này':p?.percent>0?'· '+p.percent+'% đã đọc':'';});}
