const pageFile=location.pathname.split('/').pop()||'index.html';$$('.desktop-nav a,.mobile-menu a').forEach(a=>{const href=a.getAttribute('href');if(href&&!href.includes('#')&&href.split('/').pop()===pageFile)a.setAttribute('aria-current','page');});
